package graphql

// ThemeCSS gives the locally rendered GraphiQL surface project theme colors.
const ThemeCSS = `:root{color-scheme:dark light;--docs-bg:#101820;--docs-fg:#edf3f8;--docs-card:#1b2833}html.theme-light{--docs-bg:#fff;--docs-fg:#17212b;--docs-card:#f2f5f8}body{background:var(--docs-bg);color:var(--docs-fg);font-family:system-ui,sans-serif}textarea,pre{box-sizing:border-box;width:100%;max-width:100%;background:var(--docs-card);color:var(--docs-fg);padding:.75rem;word-break:break-word}button,input,textarea{font:inherit;min-height:44px}`
